from typing import TypedDict, Literal
from langgraph.graph import StateGraph, START, END
from langgraph.types import interrupt

class RefundState(TypedDict, total=False):
    goal: str
    retrieved_sources: list[str]
    draft_answer: str
    citation_errors: list[str]
    approved: bool
    status: str

def retrieve_policy(state: RefundState):
    return {"retrieved_sources": ["refund-policy#45"]}

def draft_answer(state: RefundState):
    return {"draft_answer": "Policy says no automatic refund after 30 days. [refund-policy#45]"}

def validate_citations(state: RefundState):
    has_source = bool(state.get("retrieved_sources")) and "[refund-policy#45]" in state.get("draft_answer", "")
    return {"citation_errors": [] if has_source else ["missing refund-policy citation"]}

def human_review(state: RefundState):
    approved = interrupt({"reason": "exception or sensitive refund answer", "draft": state["draft_answer"]})
    return {"approved": bool(approved)}

def route_after_validation(state: RefundState) -> Literal["draft_answer", "human_review"]:
    return "draft_answer" if state.get("citation_errors") else "human_review"

def route_after_review(state: RefundState) -> Literal["final", "cancelled"]:
    return "final" if state.get("approved") else "cancelled"

def final(state: RefundState):
    return {"status": "done"}

def cancelled(state: RefundState):
    return {"status": "cancelled"}

graph = StateGraph(RefundState)
graph.add_node("retrieve_policy", retrieve_policy)
graph.add_node("draft_answer", draft_answer)
graph.add_node("validate_citations", validate_citations)
graph.add_node("human_review", human_review)
graph.add_node("final", final)
graph.add_node("cancelled", cancelled)
graph.add_edge(START, "retrieve_policy")
graph.add_edge("retrieve_policy", "draft_answer")
graph.add_edge("draft_answer", "validate_citations")
graph.add_conditional_edges("validate_citations", route_after_validation)
graph.add_conditional_edges("human_review", route_after_review)
graph.add_edge("final", END)
graph.add_edge("cancelled", END)

app = graph.compile()  # add a checkpointer for resumable production runs
